    sp<MockWatchdogProcessService> mMockWatchdogProcessService;
    sp<MockCarWatchdogServiceForSystem> mMockCarWatchdogServiceForSystem;
    sp<MockBinder> mMockCarWatchdogServiceForSystemBinder;
